import {bindSiteNotes} from './site-notes.js?v=20261031-player6';
import {startTraffic} from './traffic.js?v=20261031-player6';
import {createChallengeController} from './challenge-view.js?v=20261031-player6';
import {createCheckupController} from './checkup-view.js?v=20261031-player6';
import {createPublishedDailyController} from './published-daily.js?v=20261031-player6';
import {methodView,measurementView} from './method-view.js?v=20261031-player6';
import {metricSummary,manualTask,protocolOf} from './core-metrics.js?v=20261031-player6';
import {systemView,metricsView,assessmentView,rubricView,workflowView} from './core-views.js?v=20261031-player6';
import{scopeData,measurementScope,comparisonScope,projectData}from'./scope.js?v=20261031-player6';
import{qualityChart}from'./quality-chart.js?v=20261031-player6';
import{speedView}from'./speed-view.js?v=20261031-player6';
import{taskSummary,comparisonWarnings,graderDescription}from'./evidence.js?v=20261031-player6';
import{categories,esc as e,safeUrl,fmt as f,stats,selectModels,csv,validateData}from'./lib.js?v=20261031-player6';
const siteNotes=bindSiteNotes();
const main=document.querySelector('main'),pick=document.querySelector('#dataset');let fullData,data,mode='catalog',selected=new Set(),imported=null,filters={query:'',provider:'all',sort:'name',category:'all'},activeTask='all',activeProtocol='core-client-v1';
const money=x=>x==null?'—':'$'+f(x,6),percent=x=>x==null?'—':f(x*100,1)+'%',ms=x=>x==null?'—':f(x/1000,2)+' s';
const link=(url,label)=>safeUrl(url)?`<a class="source" href="${e(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a>`:'<span class="muted">未提供来源</span>';
const go=path=>{location.hash=path};
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),5000)}
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.hidden=true;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000)}
let framework;
const challenge=createChallengeController({main,toast,download,rerender:render});
const checkup=createCheckupController({main,toast,download,rerender:render,routePrefix:'selftest'});
const publishedDaily=createPublishedDailyController({main,rerender:render});
let legacyLoading=false,navSurface=null;
const isCore=()=>data.tasks.some(t=>t.grader.type==='contract');
const protocols=d=>{const sent=d.runs.filter(r=>r.status!=='skipped');return [...new Set(sent.length?sent.map(protocolOf):d.meta.protocolId?[d.meta.protocolId]:d.tasks.map(t=>t.grader.type==='contract'?'core-client-v1':'legacy-sse-v2'))].sort()};
function metricScope(){const ids=[...selected].filter(id=>data.models.some(m=>m.id===id));return ids.length>=2?comparisonScope(data,ids):ids.length?projectData(data,{modelIds:ids}):data}
function banner(){const kind=data.meta.kind;return `<div class="notice ${kind==='demo'?'demo':''}">${kind==='demo'?'<strong>模拟验收 / DEMO</strong>　全部回答与计数由本地程序预设，仅验证流程，不代表模型能力、速度或费用。':mode==='core'?'<strong>核心试测 v1 / 尚无真实成绩</strong>　本轮新增API费用0；24道题已准备，难度未校准。六个GOAT配置为历史目录，当前价格与可用性待核验。':kind==='measured'?`<strong>历史真实采集 / 旧版流程样本</strong>　当前范围 ${data.runs.length} 次请求；保留原判分和速率口径，没有补成新协议成绩。上游身份与账单未独立核验。`:'<strong>资料目录 / 无实测分数</strong>　规格与报价为注明日期的来源快照，不保证当前可用性。'}${mode==='imported'?'<br><strong>本地导入：</strong>由文件提供，未独立核验；仅当前标签页处理，未上传。':''}</div>`}
function head(title,desc,eyebrow='MODEL INTELLIGENCE',actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div><div class="head-actions">${actions}</div></div>${scopeBar()}${banner()}`}
function scopeBar(){const base=measurementScope(fullData,{batchId:document.querySelector('#batch-scope').value||'all',protocolId:activeProtocol});return `<section class="scope-bar" aria-label="全站测量范围"><label>指标口径<select id="protocol-scope" aria-label="筛选测量协议">${protocols(fullData).map(p=>`<option value="${e(p)}" ${activeProtocol===p?'selected':''}>${p==='core-client-v1'?'核心协议 v1':'历史SSE口径 v2'}</option>`).join('')}</select></label><label>评测场景<select id="category" aria-label="筛选评测场景"><option value="all">全部场景</option>${Object.entries(categories).map(([k,v])=>`<option value="${k}" ${filters.category===k?'selected':''}>${v}</option>`).join('')}</select></label><label>具体任务<select id="task-scope" aria-label="筛选具体任务"><option value="all">当前场景全部任务</option>${base.tasks.filter(t=>filters.category==='all'||t.category===filters.category).map(t=>`<option value="${e(t.id)}" ${activeTask===t.id?'selected':''}>${e(t.title)}</option>`).join('')}</select></label><span>${data.tasks.length} 道题 · ${data.runs.length} 次记录<br><small>场景、任务和顶部批次贯穿列表、详情、速度与导出；对比再取共同已尝试题。</small></span></section>`}
function currentExport(){const page=location.hash.slice(1).split('/')[0];let out;if(page==='metrics')out=metricScope();else if(page==='compare')out=comparisonScope(data,[...selected]);else if(page==='models')out=projectData(data,{modelIds:selectModels(data,filters).map(m=>m.id)});else out=data;return {...out,meta:{...out.meta,description:`导出范围：${filters.category==='all'?'全部场景':categories[filters.category]}；协议 ${activeProtocol}；任务 ${activeTask}；批次 ${document.querySelector('#batch-scope').value}；${(page==='compare'||page==='metrics'&&selected.size>=2)?'所选配置共同已尝试题':page==='models'||page==='overview'||!page?'当前可见模型列表':'当前测量范围全部配置'}；${out.tasks.map(t=>t.id).join(',')}。原数据集说明：${out.meta.description}`}};}
function stat(label,value,note){return `<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><small>${note}</small></div>`}
function empty(title,desc,button=true){return `<div class="empty"><div><strong>${title}</strong><div>${desc}</div>${button?'<button data-action="demo">查看演示数据 →</button>':''}</div></div>`}
function modelRows(models){return models.map(m=>{const s=stats(data,m.id),c=metricSummary(data,m.id),core=isCore();return `<tr><td><input type="checkbox" aria-label="对比 ${e(m.name)}" data-select="${e(m.id)}" ${selected.has(m.id)?'checked':''}></td><td><div class="model-cell"><span class="model-mark">${e(m.name[0])}</span><div><button class="link" data-model="${e(m.id)}">${e(m.name)}</button><small>${e(m.provider)} · ${e(m.reasoning||'默认配置')}</small></div></div></td><td>${percent(core?c.automaticDelivery:s.ruleDelivery)}<small>${core?c.automaticFamilies+'个自动题族':s.ruleTasks+'道旧规则题'} · 含失败</small></td><td>${percent(core?c.content:s.taskQuality)}<small>${core?c.contentTasks+'道内容已评题 / '+c.contentFamilies+'题族':s.gradedTasks+'道旧规则已评题'} · ${s.pending}次待评</small></td><td>${percent(c.format)}<small>${c.formatTasks}道新协议已检查题</small></td><td>${percent(c.completed)}<small>${c.success}/${c.attempted}次完整返回</small></td><td>${f(activeProtocol==='core-client-v1'?c.bodyTps:c.legacyTps)}<small>${activeProtocol==='core-client-v1'?'新协议；'+c.bodyTpsSamples+'个可测样本':'旧边界估计；'+c.legacyTpsSamples+'个样本'}</small></td><td>${ms(c.ttfa)}<small>成功请求中位数</small></td><td>${money(core?c.costPerQualified:s.cost)}<small>${core?({unmeasured:'未采集',pending_review:'有人工待评',unknown_cost:'存在未知费用',no_qualified:'无合格结果',available:'每个合格结果费用'})[c.costState]:'成功请求费用中位数 / USD'}</small></td></tr>`}).join('')}
function table(models,withFilters=true){return `<section class="panel"><div class="panel-head"><h2>模型一览</h2><a href="#compare">对比所选模型 ⇄</a></div>${withFilters?`<div class="filters"><input id="query" placeholder="搜索模型、服务商或标签…" aria-label="搜索模型" value="${e(filters.query)}"><select id="provider" aria-label="筛选服务商"><option value="all">所有服务商</option>${[...new Set(data.models.map(m=>m.provider))].map(p=>`<option ${filters.provider===p?'selected':''}>${e(p)}</option>`).join('')}</select><select id="sort" aria-label="排序"><option value="name">模型名称</option>${Object.entries({ruleDelivery:'规则交付率优先',completion:'完整返回率优先',tps:'TPS 优先',ttfa:'正文等待优先',price:'输入报价优先'}).map(([k,v])=>`<option value="${k}" ${filters.sort===k?'selected':''}>${v}</option>`).join('')}</select></div><p class="evidence-meta list-note">搜索、服务商和排序只控制本列表及其导出；已选对比配置保留。不同覆盖的行不构成统一排名。</p>`:''}<div class="table-wrap"><table><thead><tr><th>对比</th><th>模型 / 接口</th><th>${isCore()?"自动题交付 · 题族等权":"旧规则交付 · 题目等权"}</th><th>${isCore()?'内容分 · 题族等权':'旧规则已评通过率 · 题目等权'}</th><th>格式全满足率 · 新协议</th><th>完整返回率</th><th>正文速度</th><th>正文等待</th><th>费用估算</th></tr></thead><tbody id="model-rows">${modelRows(models)}</tbody></table></div><div class="table-foot" id="table-foot">${models.length} 个配置 · 可选 2–4 个对比 · 规则交付率含错误和超时；人工待评不算通过。<a href="#method">查看指标定义 ↗</a></div></section>`}
function chart(){return qualityChart(data,filters.category)}
function overview(){return head('用可复核指标比较模型','能力、速度、可靠性与成本分别看。先明确任务和口径，再打开回答与评分依据。','ZHUFENG / EVALUATION SYSTEM V1','<button data-go="metrics" class="primary">查看核心指标 ↗</button><button data-go="workflow">本机测试流程 ↗</button>')+`<div class="core-actions"><button data-dataset="core">核心题库 · 未采集</button><button data-dataset="offline">新协议离线验收 · 模拟</button><button data-dataset="measured">90条历史真实记录</button><a href="#system">完整评测体系与实现边界 ↗</a></div>`+table(data.models,false)+`<div class="stats">${stat('当前独立题目',f(data.tasks.length,0),'变体另标题族；题目难度待校准')}${stat('当前运行记录',f(data.runs.length,0),data.meta.kind==='demo'?'全部为模拟验收，不是实测':'当前范围，含失败')}${stat('自动验证题',f(data.tasks.filter(t=>!manualTask(t)).length,0),'仅验证声明的规则')}${stat('人工细评题',f(data.tasks.filter(manualTask).length,0),'未复核不填分')}</div><section class="panel"><div class="panel-body prose"><h2>按你的现有条件实施</h2><p>沿用本机Python/Node、GOAT API及静态站，新增API费用为0。核心计时、评分、费用与证据导出已用本机模拟链路验证。新协议没有真实模型成绩；历史90次采集保留旧口径。</p><p>代码未接入隔离执行，不发布pass@1。写作、证明和SVG有逐项锚点，但仍需要人工复核。并发、原生工具、专业知识与多模态的缺项在评测体系页明确列出。</p><div class="head-actions"><button data-go="system">评测体系 ↗</button><button data-go="tasks">24道试测题与标准 ↗</button></div></div></section>`}
function models(){return head('模型库','查找模型配置，查看公开资料、测试成绩与适用条件。','MODEL DIRECTORY','<button data-export="csv">导出比较表 ↓</button>')+table(selectModels(data,filters))}
function compare(){const models=data.models.filter(m=>selected.has(m.id)),cohort=comparisonScope(data,models.map(m=>m.id)),get=m=>stats(cohort,m.id);const fields=[['服务商 / 版本',m=>`${e(m.provider)}<small>${e(m.version)}</small>`],['共同已尝试题',m=>`${cohort.tasks.length} 道`],['规则交付率 · 题目等权（含失败）',m=>percent(get(m).ruleDelivery)+`<small>${get(m).ruleTasks} 道规则题 · ${get(m).ruleAttempts} 次尝试</small>`],['全部约束与内容同时通过 · 已评运行按题等权',m=>percent(get(m).taskQuality)+`<small>${get(m).gradedTasks} 道已评题</small>`],['已评运行通过率（重复会改变权重）',m=>percent(get(m).quality)],['已评 / 待评运行',m=>`${get(m).graded} / ${get(m).pending}`],['完整返回率',m=>percent(get(m).completion)+`<small>${get(m).successful}/${get(m).attempted} 次</small>`],['正文 TPS',m=>f(get(m).tps)+` token/s<small>${get(m).tpsSamples} 个可测样本</small>`],['输出字符 / 秒',m=>f(get(m).cps)+`<small>${get(m).cpsSamples} 个样本</small>`],['首个正文等待 / 完整耗时',m=>ms(get(m).ttfa)+' / '+ms(get(m).duration)+'<small>成功请求中位数</small>'],['规则题等权每次尝试费用',m=>money(get(m).ruleCost)+'<small>含失败；任一相关费用未知则留空</small>'],['成功请求费用中位数',m=>money(get(m).cost)],['全部尝试总费用',m=>money(get(m).totalCost)+`<small>${get(m).unknownCosts} 次费用未知</small>`],['输入 / 输出公开报价',m=>money(m.inputPrice)+' / '+money(m.outputPrice)+'<small>USD / 百万 token；详见配置来源</small>'],['配置证据',m=>`<button data-model="${e(m.id)}">查看该配置全部候选题 ↗</button>`]];if(isCore()){fields.unshift(['自动题合格交付 · 题族等权（含失败）',m=>percent(metricSummary(cohort,m.id).automaticDelivery)],['内容分 · 题族等权',m=>percent(metricSummary(cohort,m.id).content)],['格式全满足率 · 题族等权',m=>percent(metricSummary(cohort,m.id).format)],['端到端正文TPS（含等待）',m=>f(metricSummary(cohort,m.id).endToEndTps)],['每个合格结果费用',m=>money(metricSummary(cohort,m.id).costPerQualified)]);}return head('并排比较，找到取舍','自动取所选配置共同尝试过的题，保留这些题的错误与超时。输出上限、推理默认值和采集时段仍可能不同。','SIDE BY SIDE','<button data-export="csv">导出本次对比 ↓</button><button data-export="json">导出共同题证据 ↓</button>')+`<div class="compare-pick">${data.models.map(m=>`<label><input type="checkbox" aria-label="对比 ${e(m.name)}" data-select="${e(m.id)}" ${selected.has(m.id)?'checked':''}>${e(m.name)}</label>`).join('')}</div>`+(models.length<2?empty('选择至少两个模型','勾选上方模型，或在模型库中添加。',false):!cohort.tasks.length?empty('当前范围没有共同已尝试题','保留各自证据，但不汇总为可比成绩。请更换任务范围或所选配置。',false):`<div class="notice">共同范围：${cohort.tasks.map(t=>e(t.title)).join('、')}。从 ${data.tasks.length} 道候选题收窄到 ${cohort.tasks.length} 道；这不是总体能力排名。</div>`+comparisonWarnings(cohort,models).map(w=>`<div class="notice">${e(w)}</div>`).join('')+`<section class="panel"><div class="table-wrap"><table class="compare-table"><thead><tr><th>比较维度</th>${models.map(m=>`<th><button data-model="${e(m.id)}">${e(m.name)} ↗</button></th>`).join('')}</tr></thead><tbody>${fields.map(([label,value])=>`<tr><td>${label}</td>${models.map(m=>`<td>${value(m)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>共同规则题：交付与费用</h2></div>${qualityChart(cohort)}</section>`)}
function modelDetail(id){const m=data.models.find(m=>m.id===id);if(!m)return notfound();const c=metricSummary(data,id),s=stats(data,id),runs=data.runs.filter(r=>r.modelId===id);return `<a class="back" href="#models">← 返回模型库</a>`+head(e(m.name),e(m.description),'MODEL PROFILE',`<button data-toggle="${e(id)}">${selected.has(id)?'移出对比':'加入对比'} ⇄</button>`)+`<div class="stats">${stat('规则交付率 · 题目等权',percent(s.ruleDelivery),`${s.ruleTasks} 道规则题 · ${s.ruleAttempts} 次尝试，含失败`)}${stat(isCore()?'内容分 · 题族等权':'旧规则已评通过率',percent(isCore()?c.content:s.taskQuality),`${s.gradedTasks} 道已评题 · ${s.graded} 次已评 / ${s.pending} 次待评`)}${stat('完整返回率',percent(s.completion),`${s.successful}/${s.attempted} 次 · 已评运行通过率 ${percent(s.quality)}`)}${stat('正文速度',f(s.tps), 'token/s · 可可靠计数时才展示')}${stat('首个正文等待',ms(s.ttfa),'包含正文前的推理等待')}${stat('完整响应耗时',ms(s.duration),'成功请求耗时中位数')}</div><div class="detail-grid"><div><section class="panel"><div class="panel-head"><h2>分场景结果</h2><small>规则交付率（含失败）/ 规则题数</small></div><div class="panel-body">${Object.entries(categories).map(([k,v])=>{const t=stats(data,id,k);return `<div style="margin-bottom:19px"><div style="display:flex;justify-content:space-between;font-size:12px"><span>${v}</span><span>${percent(t.ruleDelivery)} · ${t.ruleTasks} 道规则题</span></div><div class="progress"><span style="width:${(t.ruleDelivery||0)*100}%"></span></div></div>`}).join('')}</div></section><section class="panel"><div class="panel-head"><h2>原始运行证据</h2><small>${runs.length} 条</small></div>${runTable(runs)}</section></div><section class="panel"><div class="panel-head"><h2>配置与来源</h2></div><div class="panel-body"><dl class="facts">${[['服务商',e(m.provider)],['版本',e(m.version)],['推理配置',e(m.reasoning||'未指定')],['上下文',f(m.contextWindow,0)+' tokens'],[m.status==='catalog'?'标称最大输出':'本配置输出上限',f(m.maxOutputTokens,0)+' tokens'],['输入报价',money(m.inputPrice)],['输出报价',money(m.outputPrice)],['缓存输入',money(m.cachedInputPrice)],['核对日期',e(m.sourceDate||'未提供')]].map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl><p class="evidence-meta">${e(m.priceNote||'价格单位 USD / 百万 token。工具调用、缓存写入、长输入及服务等级可能另计。')}</p>${link(m.sourceUrl,'打开官方来源')}</div></section></div>`}
function runTable(runs){if(!runs.length)return empty('尚无运行记录','完成测试并导入结果后，这里会展示完整回答与评分依据。',mode!=='demo');return `<div class="table-wrap"><table><thead><tr><th>任务 / 模型</th><th>状态 / 评分</th><th>耗时</th><th>证据</th></tr></thead><tbody>${runs.map(r=>{const t=data.tasks.find(t=>t.id===r.taskId),m=data.models.find(m=>m.id===r.modelId);return `<tr><td>${e(t.title)}<small>${e(m.name)}</small></td><td><span class="${r.grading.status==='passed'?'badge-pass':'badge-fail'}">${e(r.status)} / ${e(r.grading.status)}</span></td><td>${ms(r.metrics.durationMs)}</td><td><button data-run="${e(r.id)}">查看完整记录 ↗</button></td></tr>`}).join('')}</tbody></table></div>`}
function tasks(){const ts=data.tasks;return head('把能力落到具体任务','上方场景与任务范围和模型页一致。参考答案、评分方式与完整回答均可查看。','TASKS & EVIDENCE')+`<p class="count-line">${ts.length} 道题 · 当前为公开起步题库，不能用于宣称权威综合排名。</p><div class="task-grid">${ts.map(t=>`<article class="task-card"><div class="chips"><span class="tag">${categories[t.category]}</span><span class="tag">${e(t.difficulty)}</span></div><h3>${e(t.title)}</h3><p>${e(t.prompt.slice(0,115))}${t.prompt.length>115?'…':''}</p><div class="evidence-meta">${manualTask(t)?'人工复核':'规则验收'} · ${data.runs.filter(r=>r.taskId===t.id).length} 条记录</div><button data-task="${e(t.id)}">查看任务与回答 ↗</button></article>`).join('')}</div>`}
function taskDetail(id){const t=data.tasks.find(t=>t.id===id);if(!t)return notfound();return `<a class="back" href="#tasks">← 返回任务库</a>`+head(e(t.title),`${categories[t.category]} · ${e(t.difficulty)} · ${e(t.source)}`,'TASK DETAIL',`<button class="primary" data-go="answers/${e(t.id)}">同题对照 ⇄</button>`)+`<div class="two-cols"><section class="panel"><div class="panel-head"><h2>完整输入</h2></div><div class="panel-body"><pre class="evidence">${e(t.prompt)}</pre></div></section><section class="panel"><div class="panel-head"><h2>参考与验收</h2></div><div class="panel-body prose"><p>${e(t.reference)}</p><ul>${t.rubric.map(s=>`<li>${e(s)}</li>`).join('')}</ul><p class="mono">评分器：${e(t.grader.type)}</p><p>${e(graderDescription(t.grader.type))}</p><p class="evidence-meta">人工复核题在评审完成前标记 pending；规则通过也仅证明满足该题的规则。</p></div></section></div>${rubricView(t)}<section class="panel"><div class="panel-head"><h2>各配置运行记录</h2></div>${runTable(data.runs.filter(r=>r.taskId===id))}</section>`}
function runDetail(id){const r=data.runs.find(r=>r.id===id);if(!r)return notfound();const t=data.tasks.find(t=>t.id===r.taskId),m=data.models.find(m=>m.id===r.modelId);return `<a class="back" href="#task/${e(t.id)}">← 返回任务</a>`+head('原始运行记录',`${e(m.name)} / ${e(t.title)}`,'RUN EVIDENCE')+`${assessmentView(r)}${measurementView(r)}<div class="detail-grid"><div><section class="panel"><div class="panel-head"><h2>模型完整正文</h2><span class="tag">${e(r.status)}</span></div><div class="panel-body"><pre class="evidence">${e(r.output||'（未返回正文）')}</pre>${r.error?`<p class="badge-fail">错误：${e(typeof r.error==='string'?r.error:JSON.stringify(r.error))}</p>`:''}</div></section><details><summary>展开原始输入与参考答案</summary><pre class="evidence">${e(t.prompt)}</pre><p>${e(t.reference)}</p></details><details><summary>展开公开结构化记录</summary><pre class="evidence">${e(JSON.stringify(r,null,2))}</pre></details></div><section class="panel"><div class="panel-head"><h2>评分与采集条件</h2></div><div class="panel-body"><p><span class="tag">${e(r.grading.status)}</span></p><p>${e(r.grading.reason)}</p><p class="evidence-meta">${e(graderDescription(t.grader.type))}</p><dl class="facts">${[['数据类型',e(r.dataKind)],['记录时间',e(r.timestamp)],['TTFT',ms(r.metrics.ttftMs)],['首个正文',ms(r.metrics.ttfaMs)],['完整耗时',ms(r.metrics.durationMs)],['正文 TPS',f(r.metrics.outputTps)],['输出字符 / 秒',f(r.metrics.charsPerSec)],['输入 token',f(r.metrics.inputTokens,0)],['输出 token',f(r.metrics.outputTokens,0)],['推理 token',f(r.metrics.reasoningTokens,0)],['费用估算 USD',money(r.metrics.cost)],['地区',e(r.config?.region||'未记录')],['并发',f(r.config?.concurrency,0)],['声明输出上限（本题）',m.maxOutputTokens!=null&&t.maxOutputTokens!=null?f(Math.min(m.maxOutputTokens,t.maxOutputTokens),0)+' tokens':'未记录'],['缓存状态',e(r.config?.cacheState||'unknown')],['计数来源',e(r.provenance?.tokenCountSource||'unknown')],['计时口径',e(r.provenance?.tpsMethod||r.provenance?.timingSource||'未提供')],['费用依据',e(r.provenance?.costSource||'未提供')]].map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl></div></section></div>`}
function batches(){return head('每一轮测试，都有上下文','保存模型配置、任务清单、重复次数与预算；变更题库或参数时建立新批次。','TEST BATCHES')+`<section class="panel">${data.batches.length?data.batches.map(b=>`<article class="batch"><span class="tag ${b.dataKind==='demo'?'orange':''}">${e(b.status)} / ${e(b.dataKind)}</span><h3>${e(b.title)}</h3><p>${e(b.description)}</p><div class="batch-meta"><span>${b.modelIds.length} 个模型</span><span>${b.taskIds.length} 道题</span><span>${f(b.config?.repeats,0)} 次重复</span><span>并发 ${f(b.config?.concurrency,0)}</span><span>预算 ${money(b.config?.budgetUsd)}</span></div><p class="mono">${e(b.createdAt)} · ${e(b.config?.region||'待指定')}</p><details><summary>批次记录与运行结果</summary>${runTable(data.runs.filter(r=>r.batchId===b.id))}</details></article>`).join(''):empty('尚无批次','使用运行器创建第一个测试计划。',false)}</section>`}
function method(){return head('让结论经得起复核','测量定义、评分算法和证据边界。','METHODOLOGY / CORE V1')+methodView()}
function dataPage(){return head('把你的测试，带进工作台','导入运行器导出的 v1 JSON，查看同一套页面与证据。文件留在当前标签页。','DATA WORKSPACE')+`<div class="two-cols"><section class="panel"><div class="panel-head"><h2>导入测试结果</h2><small>JSON · 最大 10 MB</small></div><div class="panel-body"><div class="upload"><h3>选择公开结果文件</h3><p>通过公开字段白名单、引用和跨字段指标校验后加载；未知扩展字段不保留。请先使用运行器 export 命令，避免导入私有日志。</p><input type="file" id="import-file" accept=".json,application/json" aria-label="选择测评 JSON 文件"></div><p class="evidence-meta">刷新页面会清除导入数据。需要保存时，请下载 JSON 文件。文件中不应包含密钥、账号凭据或第三方隐私。</p></div></section><section class="panel"><div class="panel-head"><h2>导出与重现</h2></div><div class="panel-body"><div class="head-actions"><button data-export="json" class="primary">下载当前 JSON</button><button data-export="csv">下载 CSV</button></div><p class="evidence-meta">此页导出当前批次、场景与任务范围的全部配置；模型列表导出可见行，对比页导出共同已尝试题。JSON 保留对应证据，CSV 为相同范围的模型汇总。CSV 已处理常见公式前缀。</p><h3 style="margin-top:27px">本地运行</h3><pre class="evidence">python -m runner plan --config config.example.json --dataset dist/data/catalog.json\npython -m runner --help</pre><p class="evidence-meta">先完成计划检查，再在本地配置 API 环境变量与预算执行。运行器源代码及说明随项目交付。</p></div></section></div><section class="panel" id="export-preview" hidden><div class="panel-head"><h2>完整导出内容</h2><button data-action="copy-export">复制内容</button></div><div class="panel-body"><p class="evidence-meta">浏览器如未保存文件，可复制下方完整内容自行保存。JSON 保留原始记录，CSV 为汇总表。</p><textarea id="export-content" aria-label="完整导出内容" readonly rows="12" style="width:100%;font-family:monospace;background:var(--bg);color:var(--ink);border:1px solid var(--line);padding:14px;border-radius:8px"></textarea></div></section><section class="panel"><div class="panel-head"><h2>当前数据摘要</h2></div><div class="panel-body"><dl class="facts">${[['名称',e(data.meta.title)],['类型',e(data.meta.kind)],['更新时间',e(data.meta.updatedAt)],['模型 / 题目',data.models.length+' / '+data.tasks.length],['运行 / 批次',data.runs.length+' / '+data.batches.length]].map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl><p class="evidence-meta">${e(data.meta.description)}</p></div></section>`}
function speed(){return head('速度，不止一个 TPS','把等待、正文输出、完整耗时与失败放在同一张表。','SPEED / RELIABILITY')+speedView(data,'all')}
function matrix(){const models=selected.size?data.models.filter(m=>selected.has(m.id)):data.models;return head('每一道题，发生了什么','按题目查看覆盖、已评结果、待评与未完整返回。点击有记录的单元格打开最后一次尝试；通过率与请求成功率分别解读。','COVERAGE MATRIX')+`<p class="count-line">${models.length} 个配置 × ${data.tasks.length} 道题 · ${selected.size?'仅展示已选配置':'可在模型库选择最多4个配置以缩小范围'}</p><section class="panel"><div class="table-wrap"><table class="matrix-table"><thead><tr><th>任务</th>${models.map(m=>`<th>${e(m.name)}</th>`).join('')}</tr></thead><tbody>${data.tasks.map(t=>`<tr><td><button class="link" data-task="${e(t.id)}">${e(t.title)}</button><small>${categories[t.category]}</small></td>${models.map(m=>{const s=taskSummary(data,m.id,t.id);return `<td>${s.latest?`<button data-run="${e(s.latest.id)}" aria-label="查看${e(m.name)}在${e(t.title)}上的最后一次尝试"><span class="${s.failed||s.requestErrors?'badge-fail':'badge-pass'}">${s.passed+s.failed?`${s.passed}/${s.passed+s.failed} 已评通过`:s.pending?`${s.pending} 待评`:s.requestErrors?'未完整返回':s.skipped?'已跳过':'未测'}</span></button><small>${s.requestErrors} 未完整返回 · ${s.pending} 待评 · ${s.skipped} 跳过</small>`:'<span class="muted">未测</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="table-foot">每格分母仅包括已评分的成功回答。未完整返回、未评分与未测不混入通过率。单元格保留多次记录计数；完整记录可从任务详情查看。</div></section>`}
function answerCompare(id){const t=data.tasks.find(t=>t.id===id);if(!t)return notfound();const candidates=data.models.filter(m=>data.runs.some(r=>r.modelId===m.id&&r.taskId===id));const models=selected.size?data.models.filter(m=>selected.has(m.id)):candidates.slice(0,4);return `<a class="back" href="#task/${e(id)}">← 返回任务详情</a>`+head('同题对照：'+e(t.title),'每列展示当前范围内按数据文件顺序排列的最后一次尝试，包括失败。可在模型库选择2–4个配置进行对照。','ANSWER COMPARISON')+`<details><summary>查看相同输入与评分标准</summary><pre class="evidence">${e(t.prompt)}</pre><p>${e(t.reference)}</p><ul>${t.rubric.map(x=>`<li>${e(x)}</li>`).join('')}</ul></details>`+(models.length?`<div class="answer-grid">${models.map(m=>{const s=taskSummary(data,m.id,id),r=s.latest;return `<article class="panel"><div class="panel-head"><h2>${e(m.name)}</h2></div><div class="panel-body">${r?`<p><span class="tag">${e(r.status)} / ${e(r.grading.status)}</span></p><p class="evidence-meta">${ms(r.metrics.durationMs)} · ${money(r.metrics.cost)} 估算 · 共${s.runs.length}次尝试</p><pre class="evidence">${e(r.output||'（未返回正文）')}</pre><p class="evidence-meta">${e(r.error||r.grading.reason)}</p><button data-run="${e(r.id)}">打开完整证据 ↗</button><details><summary>此配置本题全部记录</summary>${s.runs.map(x=>`<p><button data-run="${e(x.id)}">${e(x.status)} / ${e(x.grading.status)} · ${e(x.timestamp)}</button></p>`).join('')}</details>`:'<p class="muted">当前范围中尚无该配置的这道题记录。</p>'}</div></article>`}).join('')}</div>`:empty('当前题目尚无运行','选择其他批次或完成采集后再对照。',false))}
function notfound(){return head('没有找到这条记录','记录可能不属于当前数据集，请切换数据来源或返回模型库。')+empty('记录不存在','请选择当前数据集中的模型、题目或运行。',false)}
function exportPreview(){return `<section class="panel" id="export-preview" hidden><div class="panel-head"><h2>本次完整导出内容</h2><button data-action="copy-export">复制内容</button></div><div class="panel-body"><p class="evidence-meta">此内容与本次下载完全相同，可直接核对范围和数值。JSON 包含对应证据，CSV 为同一范围的模型汇总。</p><textarea id="export-content" aria-label="完整导出内容" readonly rows="12" style="width:100%;font-family:monospace;background:var(--bg);color:var(--ink);border:1px solid var(--line);padding:14px;border-radius:8px"></textarea></div></section>`}
function render(){const route=location.hash.slice(1).split('/');const onPublished=!route[0]||route[0]==='checkup',onTools=route[0]==='selftest',onDaily=onPublished||onTools,onChallenge=route[0]==='challenge';document.body.classList.toggle('daily-mode',onDaily);document.body.classList.toggle('published-mode',onPublished);document.body.classList.toggle('published-home',onPublished&&(!route[1]||route[1]==='results'));document.querySelector('#legacy-controls').hidden=onDaily||onChallenge;document.querySelector('#challenge-context').hidden=!onChallenge;document.querySelector('#checkup-context').hidden=!onDaily;const surface=onDaily?'daily':'advanced';if(surface!==navSurface){document.querySelector('#advanced-nav').open=!onDaily;navSurface=surface}if(onDaily){const active=onTools?'selftest':('checkup'+(['works','play'].includes(route[1])?'/works':route[1]==='repairs'?'/repairs':['results','compare','model','how','season','purpose','reasoning','edit','memory','honesty','visual','receipt','zebra'].includes(route[1])?'/results':['contact','audience','privacy'].includes(route[1])?'/'+route[1]:''));document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===active));document.querySelector('#checkup-context').innerHTML=onTools?'<span class="tag">手动自测工具</span><span>粘贴已有回答 · 不调用模型</span>':(route[1]==='season'?'<span class="tag">新一期 · 待实测</span><span>题面与评分已定义 · 0 次模型调用</span>':'<span class="tag">第一期 · 5 个型号</span><span>原八题答卷 · 原成绩保留</span>');main.innerHTML=onTools?'<div class="checkup-warning">这里保留旧版六项录入工具。新版七项百分制与账单20分项目请看已发布实测；本工具的历史分档不作为新总分。<a href="#checkup">返回已发布实测 →</a></div>'+checkup.render(route[1]||'').replaceAll('#checkup','#selftest'):publishedDaily.render(route.slice(1));siteNotes.refresh();document.title=(main.querySelector('h1')?.textContent||'国产 AI 模型实测')+' · 国产 AI 模型实测 · 逐风03';return}if(onChallenge){document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav==='challenge'));main.innerHTML=challenge.render(route[1]||'');document.title=(main.querySelector('h1')?.textContent||'挑战题库 V2')+' · 国产 AI 模型实测 · 逐风03';return}if(!data){if(!legacyLoading){legacyLoading=true;load('core').finally(()=>{legacyLoading=false})}return}data=measurementScope(fullData,{batchId:document.querySelector('#batch-scope').value||'all',category:filters.category,taskId:activeTask,protocolId:activeProtocol});const [rawPage,id]=location.hash.slice(1).split('/');const page=rawPage||'overview';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page||(page==='model'&&a.dataset.nav==='models')||(['task','run','answers'].includes(page)&&a.dataset.nav==='tasks')));document.querySelector('#compare-count').textContent=selected.size;const views={system:()=>head('评测体系与实现边界','指标、测试方法、评分口径与当前缺项。','EVALUATION FRAMEWORK')+systemView(framework),metrics:()=>head('核心指标，逐项可查','内容与格式分开；新旧速率分开；未知不补零。选中2个以上配置时只汇总共同已尝试题。','CORE METRICS','<button data-export="csv">导出指标 CSV ↓</button><button data-export="json">导出对应证据 ↓</button>')+metricsView(metricScope()),workflow:()=>head('本机测试与复核流程','不收集网页密钥；从离线验收到公开结果。','LOCAL WORKFLOW')+workflowView(),overview,models,compare,tasks,batches,matrix,speed,answers:()=>answerCompare(id),method,data:dataPage,model:()=>modelDetail(id),task:()=>taskDetail(id),run:()=>runDetail(id)};main.innerHTML=(views[page]||notfound)();if(!main.querySelector('#export-preview'))main.insertAdjacentHTML('beforeend',exportPreview());document.title=`${main.querySelector('h1')?.textContent||'测评'} · 国产 AI 模型实测 · 逐风03`}
let loadSequence=0;
async function load(kind){const sequence=++loadSequence;try{if(!framework)framework=await(await fetch('data/framework.json')).json();const next=kind==='imported'?imported:await(await fetch(`data/${kind}.json`)).json();if(sequence!==loadSequence)return;const clean=validateData(next);fullData=clean;data=clean;mode=kind;activeProtocol=protocols(clean)[0]||'core-client-v1';document.querySelector('#batch-scope').innerHTML='<option value="all">全部批次</option>'+next.batches.map(b=>`<option value="${e(b.id)}">${e(b.title)}</option>`).join('');selected.clear();activeTask='all';filters={query:'',provider:'all',sort:'name',category:'all'};pick.value=kind;render()}catch(err){if(sequence!==loadSequence)return;pick.value=mode;toast('数据加载失败：'+err.message);if(!data)main.textContent='数据读取失败，请使用 HTTP 服务打开网站并检查数据文件。'}}
main.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.dataset)load(b.dataset.dataset);if(b.dataset.reviewTemplate){const r=data.runs.find(r=>r.id===b.dataset.reviewTemplate),t=data.tasks.find(t=>t.id===r?.taskId);if(t?.grader.criteria){const content=JSON.stringify({reviewer:'',items:t.grader.criteria.map(c=>({id:c.id,awarded:null,reason:''}))},null,2);const preview=document.querySelector('#export-preview');preview.hidden=false;document.querySelector('#export-content').value=content;preview.scrollIntoView({block:'start'});download(content,'rubric-review-template.json','application/json');}}if(b.dataset.go)go(b.dataset.go);if(b.dataset.model)go('model/'+b.dataset.model);if(b.dataset.task)go('task/'+b.dataset.task);if(b.dataset.run)go('run/'+b.dataset.run);if(b.dataset.action==='demo'){pick.value='demo';load('demo')}if(b.dataset.action==='copy-export'){const text=document.querySelector('#export-content');if(text){text.focus();text.select();navigator.clipboard?.writeText(text.value).then(()=>toast('已复制导出内容')).catch(()=>toast('请按 Ctrl+C 复制已选中的内容'))}}if(b.dataset.export){const content=b.dataset.export==='json'?JSON.stringify(currentExport(),null,2):csv(currentExport());const preview=document.querySelector('#export-preview');if(preview){preview.hidden=false;document.querySelector('#export-content').value=content;preview.scrollIntoView({block:'start',behavior:'smooth'});}download(content,`zhufeng-${data.meta.kind}.${b.dataset.export==='json'?'json':'csv'}`,b.dataset.export==='json'?'application/json':'text/csv;charset=utf-8')}if(b.dataset.taskCategory){filters.category=b.dataset.taskCategory;activeTask='all';render()}if(b.dataset.toggle){toggle(b.dataset.toggle);render()}});
function toggle(id){if(selected.has(id))selected.delete(id);else if(selected.size<4)selected.add(id);else toast('最多同时对比 4 个模型');document.querySelector('#compare-count').textContent=selected.size}
main.addEventListener('change',async ev=>{const el=ev.target;if(el.dataset.select){toggle(el.dataset.select);el.checked=selected.has(el.dataset.select);if(location.hash==='#compare')render();return}if(el.id==='protocol-scope'){activeProtocol=el.value;activeTask='all';render();return}if(el.id==='task-scope'){activeTask=el.value;render();return}if(['provider','category','sort'].includes(el.id)){filters[el.id]=el.value;if(el.id==='category')activeTask='all';render();return}if(el.id==='import-file'){try{const file=el.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('文件超过 10 MB');const parsed=JSON.parse(await file.text());imported=validateData(parsed);if(!pick.querySelector('[value=imported]'))pick.add(new Option('本地导入 · 未独立核验','imported'));await load('imported');toast('已导入；数据仅保留在当前标签页')}catch(err){toast('导入失败：'+err.message);el.value=''}}});
main.addEventListener('input',ev=>{if(ev.target.id==='query'){filters.query=ev.target.value;const ms=selectModels(data,filters);document.querySelector('#model-rows').innerHTML=modelRows(ms);document.querySelector('#table-foot').textContent=`找到 ${ms.length} 个模型配置 · 最多选 4 个对比`}});
pick.addEventListener('change',()=>load(pick.value));document.querySelector('#batch-scope').addEventListener('change',ev=>{data=scopeData(fullData,ev.target.value);if(!protocols(data).includes(activeProtocol))activeProtocol=protocols(data)[0]||'core-client-v1';selected=new Set([...selected].filter(id=>data.models.some(m=>m.id===id)));activeTask='all';filters.provider='all';render()});window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true});window.scrollTo(0,0)});function syncTheme(){const dark=document.body.classList.contains('dark'),button=document.querySelector('#theme-published');button.setAttribute('aria-pressed',String(dark));button.title=dark?'切换至浅色模式':'切换至深色模式';}document.querySelectorAll('#theme,#theme-mobile,#theme-published').forEach(button=>button.addEventListener('click',()=>{document.body.classList.toggle('dark');syncTheme();try{localStorage.setItem('zhufeng-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}}));try{if(localStorage.getItem('zhufeng-theme')==='dark')document.body.classList.add('dark')}catch{}syncTheme();document.querySelector('.skip').addEventListener('click',ev=>{ev.preventDefault();main.focus()});render();

startTraffic();
